export function checkPlan(steps) {
  const problems = [];
  steps.forEach((s, i) => {
    if (s.op === 'renameColumn') {
      problems.push({ step: i, code: 'one-step-rename' });
    } else if (s.op === 'addColumn') {
      if (s.nullable === false && (s.default === undefined || s.default === null)) {
        problems.push({ step: i, code: 'not-null-without-default' });
      }
    } else if (s.op === 'dropColumn') {
      const copiedLater = steps
        .slice(i + 1)
        .some((b) => b.op === 'backfill' && b.table === s.table && b.from === s.column);
      if (copiedLater) problems.push({ step: i, code: 'drop-before-backfill' });
    }
  });
  return problems;
}

fund-js/25-schema-changes-under-live-tra.explanation:
Walk the steps once with their index. A rename and a NOT NULL add are local checks; a drop looks ahead:

```js
} else if (s.op === 'dropColumn') {
  const copiedLater = steps
    .slice(i + 1)
    .some((b) => b.op === 'backfill' && b.table === s.table && b.from === s.column);
  if (copiedLater) problems.push({ step: i, code: 'drop-before-backfill' });
}
```

The tests catch two plausible-wrong versions. A truthiness check such as `!s.default` rejects the valid defaults `0`, `''` and `false`, while `default: null` must still be rejected, so compare against `undefined` and `null` explicitly. A drop check that ignores the table, or that also looks at EARLIER backfills, flags the correct contract step of a safe plan. The NOT NULL rule mirrors the databases: once a table has rows, SQLite and Postgres both refuse `ADD COLUMN ... NOT NULL` without a non-null default.

