const normalize = (email) => email.trim().toLowerCase();

export async function backfill(store, batchSize) {
  let after = await store.loadCheckpoint();
  let written = 0;
  for (;;) {
    const rows = await store.readAfter(after, batchSize);
    for (const row of rows) {
      if (row.emailNormalized !== null) continue;
      await store.write(row.id, normalize(row.email));
      written++;
    }
    if (rows.length > 0) {
      after = rows[rows.length - 1].id;
      await store.saveCheckpoint(after);
    }
    if (rows.length < batchSize) return written;
  }
}

fund-js/25-schema-changes-under-live-tra.explanation:
Read keyed batches from the saved position, write only unset rows, and move the checkpoint only after the batch is written:

```js
let after = await store.loadCheckpoint();
for (;;) {
  const rows = await store.readAfter(after, batchSize);
  for (const row of rows) {
    if (row.emailNormalized !== null) continue;   // done by the new code or an earlier run
    await store.write(row.id, normalize(row.email));
    written++;
  }
  if (rows.length > 0) {
    after = rows[rows.length - 1].id;
    await store.saveCheckpoint(after);           // AFTER the writes
  }
  if (rows.length < batchSize) return written;
}
```

The tests catch three plausible-wrong versions. Saving the checkpoint BEFORE the batch's writes means a crash mid-batch is resumed after rows that were never written, and they stay NULL forever. Starting every run from 0 ignores the checkpoint (wasted hours on a big table). Testing `if (row.emailNormalized)` by truthiness treats the empty string as unset, so every run rewrites those rows and the job is never idempotent.

