const PHASES = {
  'dual-write': { writeOld: true, readFrom: 'name' },
  'read-new': { writeOld: true, readFrom: 'fullName' },
  'new-only': { writeOld: false, readFrom: 'fullName' },
};

export function makeUserRepo(db, phase) {
  if (!Object.hasOwn(PHASES, phase)) throw new Error(`unknown migration phase: ${phase}`);
  const { writeOld, readFrom } = PHASES[phase];
  return {
    async save(id, fullName) {
      await db.put(id, writeOld ? { name: fullName, fullName } : { fullName });
    },
    async get(id) {
      const row = await db.get(id);
      return row ? { id, fullName: row[readFrom] } : null;
    },
  };
}

fund-js/25-schema-changes-under-live-tra.explanation:
Describe the phases as data and let `save` and `get` follow it:

```js
const PHASES = {
  'dual-write': { writeOld: true,  readFrom: 'name' },
  'read-new':   { writeOld: true,  readFrom: 'fullName' },
  'new-only':   { writeOld: false, readFrom: 'fullName' },
};
if (!Object.hasOwn(PHASES, phase)) throw new Error(`unknown migration phase: ${phase}`);
```

`Object.hasOwn` (not `PHASES[phase]` alone) also refuses names such as `'toString'` that every object inherits.

The tests catch two plausible-wrong versions. A "smart" read of `row.fullName ?? row.name` in every phase serves Grace's stale name: while old pods still write only `name`, a set `fullName` is not proof that it is current. Switching the writes together with the reads in `'read-new'` leaves the old column frozen, so reports, old consumers and a rollback lose every later rename.
